import WebSocket from 'ws';
import { createServer, IncomingMessage } from 'http';
import { createHash, randomBytes, timingSafeEqual } from 'crypto';
import { parse as parseUrl } from 'url';
import { EventEmitter } from 'events';

interface SessionToken {
  userId: string;
  nonce: string;
  expires: number;
}

const activeSessions = new Map<string, SessionToken>();
const uploadHandlers = new Map<string, WebSocket>();

function generateSessionToken(userId: string): string {
  const nonce = randomBytes(16).toString('hex');
  const expires = Date.now() + 3600000;
  const token = createHash('sha256')
    .update(`${userId}:${nonce}:${expires}`)
    .digest('hex');
  activeSessions.set(token, { userId, nonce, expires });
  return token;
}

function validateOrigin(origin: string | undefined, allowedOrigins: string[]): boolean {
  if (!origin) return false;
  return allowedOrigins.some(allowed => {
    const normalizedOrigin = origin.toLowerCase().trim();
    const normalizedAllowed = allowed.toLowerCase().trim();
    return normalizedOrigin === normalizedAllowed;
  });
}

function extractTokenFromProtocol(protocols: string | undefined): string | null {
  if (!protocols) return null;
  const parts = protocols.split(',').map(p => p.trim());
  const authProto = parts.find(p => p.startsWith('auth-'));
  return authProto ? authProto.substring(5) : null;
}

function verifySession(token: string): SessionToken | null {
  const session = activeSessions.get(token);
  if (!session) return null;
  if (Date.now() > session.expires) {
    activeSessions.delete(token);
    return null;
  }
  return session;
}

class UploadProcessor extends EventEmitter {
  private ws: WebSocket;
  private authenticated: boolean = false;
  private userId: string | null = null;

  constructor(ws: WebSocket, session: SessionToken | null) {
    super();
    this.ws = ws;
    if (session) {
      this.authenticated = true;
      this.userId = session.userId;
    }
    this.setupHandlers();
  }

  private setupHandlers(): void {
    this.ws.on('message', (data: Buffer) => {
      this.handleMessage(data);
    });
    this.ws.on('close', () => this.cleanup());
    this.ws.on('error', () => this.cleanup());
  }

  private handleMessage(data: Buffer): void {
    if (!this.authenticated) {
      this.ws.close(4001, 'Unauthorized');
      return;
    }
    try {
      // Ensure there are enough bytes for the 4-byte header before reading it.
      if (data.length < 4) {
        this.ws.close(4003, 'Invalid message format');
        return;
      }
      const header = data.slice(0, 4).readUInt32BE(0);
      const chunkType = (header >>> 24) & 0xFF;
      const chunkSize = header & 0x00FFFFFF;
      if (chunkSize > 10 * 1024 * 1024) {
        this.ws.close(4002, 'Chunk too large');
        return;
      }
      // Validate that the declared chunkSize matches the actual received payload length.
      // This prevents silently processing truncated/mismatched payloads.
      if (data.length - 4 !== chunkSize) {
        this.ws.close(4004, 'Payload length mismatch');
        return;
      }
      const payload = data.slice(4, 4 + chunkSize);
      this.processChunk(chunkType, payload);
    } catch (e) {
      this.ws.close(4003, 'Invalid message format');
    }
  }

  private processChunk(type: number, payload: Buffer): void {
    this.emit('chunk', { type, payload, userId: this.userId });
  }

  private cleanup(): void {
    this.removeAllListeners();
  }
}

function createUploadServer(config: { port: number; allowedOrigins: string[] }) {
  const server = createServer();
  const wss = new WebSocket.Server({
    server,
    verifyClient: (info: { origin: string; secure: boolean; req: IncomingMessage }, callback) => {
      const { origin, req } = info;
      const url = parseUrl(req.url || '', true);
      const upgradeHeader = req.headers['upgrade'];

      if (!upgradeHeader || upgradeHeader.toLowerCase() !== 'websocket') {
        callback(false, 400, 'Invalid upgrade request');
        return;
      }

      const token = extractTokenFromProtocol(req.headers['sec-websocket-protocol']);
      const cookieToken = extractCookieToken(req.headers['cookie']);
      const effectiveToken = token || cookieToken;

      if (!effectiveToken) {
        callback(false, 401, 'No authentication token');
        return;
      }

      const session = verifySession(effectiveToken);
      if (!session) {
        callback(false, 401, 'Invalid or expired session');
        return;
      }

      // Origin validation - always enforce regardless of client type
      const originValid = validateOrigin(origin, config.allowedOrigins);

      if (!originValid) {
        callback(false, 403, 'Origin not allowed');
        return;
      }

      (req as any).__session = session;
      callback(true);
    }
  });

  wss.on('connection', (ws: WebSocket, req: IncomingMessage) => {
    const session = (req as any).__session as SessionToken;
    const processor = new UploadProcessor(ws, session);
    uploadHandlers.set(session.userId, ws);

    processor.on('chunk', (chunk) => {
      console.log(`Processing chunk type ${chunk.type} for user ${chunk.userId}`);
    });
  });

  server.listen(config.port);
  return { server, wss };
}

function extractCookieToken(cookieHeader: string | undefined): string | null {
  if (!cookieHeader) return null;
  const cookies = cookieHeader.split(';').map(c => c.trim());
  const sessionCookie = cookies.find(c => c.startsWith('session_token='));
  return sessionCookie ? sessionCookie.split('=')[1] : null;
}

